import {compareStockPurchases,supplyLines} from './tank-stock-cost.js';
import {SUPPLY_KINDS,normalizeStockPurchasing} from './tank-stock-supply.js';
import {esc,fmt} from './tank-visuals.js';
const money=(n,c)=>Number.isFinite(n)?c+' '+fmt(n,2):'待報價';
const table=(head,rows)=>`<table><thead><tr>${head.map(x=>'<th>'+esc(x)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</tbody></table>`;
export function stockSupplyCSVRows(r){
  const p=r.input.stockPurchasing;if(!p?.offers.length&&!p?.plans.length)return [];
  const s=r.stockPlan,compare=compareStockPurchases(r),rows=[[],['板料報價與實際採購（整張／餘板／裁切料）'],['幣別',p.currency],['已套用且已報價金額',s.knownCost],['未報價原板張數',s.unpricedSheets],['金額範圍','僅已確認且已排入板料；不含未填加工／運費／稅費，不是全槽總成本。'],['料源','種類','名稱','供應商／庫位','材質','板厚 mm','密度 kg/m³','可用長 mm','可用寬 mm','可供數量','每片單價','一次費用','本次採用量','供料尚餘','本次金額','原板編號','備註']];
  const lines=supplyLines(r.sheets,p.offers);
  for(const o of p.offers){const used=lines.find(x=>x.id===o.id);rows.push([o.id,SUPPLY_KINDS[o.kind],o.name,o.supplier,o.material,o.thickness??'待填',o.density??'依唯一材料組配對',o.length??'待填',o.width??'待填',o.quantity??(o.kind==='standard'?'不限量，需確認':'待填'),o.unitPrice??'待報價',o.fee,used?.used??0,o.quantity===null?(o.kind==='standard'?'不限量':'待填'):o.quantity-(used?.used??0),used?.subtotal??(o.unitPrice===null?'待報價':0),used?.sheetIDs.join(' / ')??'',o.note]);}
  rows.push([],['已套用原板','料源','種類','實際長 mm','實際寬 mm','單片價','本張攤入一次費用','本張金額']);for(const sheet of r.sheets)rows.push([sheet.id,sheet.offerId??'未指定報價',SUPPLY_KINDS[sheet.sourceKind]??'整張估排',sheet.length,sheet.width,sheet.unitPrice??'待報價',sheet.fee??'待報價',Number.isFinite(sheet.unitPrice)?sheet.unitPrice+sheet.fee:'待報價']);
  rows.push([],['材質','板厚 mm','方案','可完整排入','採購金額 '+p.currency,'片數','採購重量 kg','餘料損耗 kg','可保留矩形餘板 m²','全槽已知焊長 mm','使用料源','搜尋範圍']);for(const item of compare.groups)for(const o of item.options)rows.push([item.group.material,item.group.thickness,o.name,o.feasible?'是':o.reason,o.cost??'未完整',o.sheetCount??'未完整',o.weight??'未完整',o.offcutWeight??'未完整',o.freeArea===undefined?'未完整':o.freeArea/1e6,o.knownWeldLength??'未完整',o.lines?.map(l=>l.id+' × '+l.used).join(' / ')??'',item.limited?'已達搜尋上限，可能有其他排法':'有限啟發式搜尋，未保證全域最低']);
  for(const x of [...s.purchasePending,...normalizeStockPurchasing(p).pending])rows.push(['採購待核',x.message]);return rows;
}
export function stockSupplyPages(r,page){
  const p=r.input.stockPurchasing;if(!p?.offers.length&&!p?.plans.length)return [];
  const s=r.stockPlan,lines=supplyLines(r.sheets,p.offers),pages=[],pending=[...s.purchasePending,...normalizeStockPurchasing(p).pending];
  for(let i=0;i<lines.length||i===0;i+=10)pages.push(page('已套用板料採購',`<h1>板料採購與報價</h1><p>已計 ${money(s.knownCost,p.currency)}；另有 ${s.unpricedSheets} 張原板未報價。${s.procurementComplete?'':'仍有毛坯資料待補，僅列可排部分。'}</p>${table(['料源／材質','實際尺寸 mm','本次量／尚餘','每片價','一次費','小計'],lines.slice(i,i+10).map(l=>[l.id+' '+(l.name||SUPPLY_KINDS[l.kind])+' / '+l.material+' t'+fmt(l.thickness),fmt(l.length)+' × '+fmt(l.width),l.used+' / '+(l.remaining===null?'不限量':l.remaining),money(l.unitPrice,p.currency),money(l.fee,p.currency),money(l.subtotal,p.currency)]))}<p>料源餘量只扣本次採購量，不因重算／列印反覆扣除。原板編號對應後頁排料，BOM 列出來源。單價按每張／片；一次費按每筆供料收一次。本表不含未報價加工、稅費及其他成本，未折抵廢料回收價。</p>${pending.slice(0,10).map(x=>'<p class="notice">'+esc(x.message)+'</p>').join('')}`));
  const c=compareStockPurchases(r);for(const item of c.groups){if(!item.offers.length)continue;pages.push(page('板料買法比較',`<h1>${esc(item.group.material)} · t${fmt(item.group.thickness)} mm</h1><p>${c.partial?'僅比較已確認毛坯；待補項不當零料。 ':''}${item.saving===null?'整張報價未齊，節省金額待核。':'與已報價整張方案比，可少花 '+money(item.saving,p.currency)+'。'}</p>${table(['方案','金額','張／片','採購 kg','餘料 kg','全槽焊長 m'],item.options.map(o=>[o.name,o.feasible?money(o.cost,p.currency):'未完整',o.sheetCount??'—',o.weight===null||o.weight===undefined?'待核':fmt(o.weight,2),o.offcutWeight===null||o.offcutWeight===undefined?'待核':fmt(o.offcutWeight,2),o.knownWeldLength===undefined?'—':fmt(o.knownWeldLength/1000,2)]))}${item.best?'<h2>已報價方案中較省的料源組合</h2>'+table(['料源','尺寸 mm','用量／餘量','金額'],item.best.lines.map(l=>[l.id+' '+(l.name||SUPPLY_KINDS[l.kind]),fmt(l.length)+' × '+fmt(l.width),l.used+' / '+(l.remaining===null?'不限量':l.remaining),money(l.subtotal,p.currency)]))+'<p>本組建議為比較結果，是否已套用以「已套用板料採購」及實際原板為準。改分片須核對捲板／接縫，焊工與吊運未報價時不計入省款。</p>':'<p>可用數量、尺寸或報價不足；本次未找到完整排法。</p>'}<p>${item.limited?'已達搜尋範圍上限；':''}以矩形毛坯含刀縫逐張排料，有限搜尋未保證最低金額；不同材質、板厚與密度不混用。</p>`));}
  for(let i=0;i<p.offers.length;i+=10)pages.push(page('供料報價紀錄',`<h1>供料報價紀錄 · ${esc(p.currency)}</h1>${table(['料源／種類','材質／厚度','可用矩形 mm','數量','每片價','一次費'],p.offers.slice(i,i+10).map(o=>[o.id+' '+(o.name||SUPPLY_KINDS[o.kind]),o.material+' / t'+fmt(o.thickness),o.length&&o.width?fmt(o.length)+' × '+fmt(o.width):'待填',o.quantity===null?(o.kind==='standard'?'不限量，需確認':'待填'):o.quantity,money(o.unitPrice,p.currency),money(o.fee,p.currency)]))}<p>餘板與裁切料為有限供量，0 為無庫存；報價空白為未知，明確填 0 才以零成本比較。尺寸須為避開缺角／孔洞／受損邊的可用矩形，未在孔洞內套料。不同幣別不能相加，換幣須重新報價。供應商、庫位、備註與原板對應見 CSV。</p>`));return pages;
}
